inline const APR *GetAPR(const void *buf) {
  return ::flatbuffers::GetRoot<APR>(buf);
}

inline const APR *GetSizePrefixedAPR(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<APR>(buf);
}

inline const char *APRIdentifier() {
  return "$APR";
}

inline bool APRBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, APRIdentifier());
}

inline bool SizePrefixedAPRBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, APRIdentifier(), true);
}

template <bool B = false>
inline bool VerifyAPRBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<APR>(APRIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedAPRBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<APR>(APRIdentifier());
}

inline void FinishAPRBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<APR> root) {
  fbb.Finish(root, APRIdentifier());
}

inline void FinishSizePrefixedAPRBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<APR> root) {
  fbb.FinishSizePrefixed(root, APRIdentifier());
}

inline std::unique_ptr<APRT> UnPackAPR(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<APRT>(GetAPR(buf)->UnPack(res));
}

inline std::unique_ptr<APRT> UnPackSizePrefixedAPR(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<APRT>(GetSizePrefixedAPR(buf)->UnPack(res));
}

